describe('Error Toast Notification', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display error toast notification when action fails', () => {
    // Intercept the API call to simulate failure
    cy.intercept('POST', '/api/save-data', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('saveDataFailed');

    // Attempt to save data
    cy.get('[data-testid="save-button"]').click();

    // Wait for the failed API call
    cy.wait('@saveDataFailed');

    // Verify error toast is visible
    cy.get('[data-testid="error-toast"]')
      .should('be.visible')
      .should('contain', 'Error')
      .should('contain', 'Internal server error');

    // Verify toast has a close button
    cy.get('[data-testid="error-toast-close-btn"]')
      .should('be.visible')
      .click();

    // Verify toast is removed from the DOM
    cy.get('[data-testid="error-toast"]').should('not.exist');
  });

  it('should not display error toast when action succeeds', () => {
    // Intercept the API call to simulate success
    cy.intercept('POST', '/api/save-data', {
      statusCode: 200,
      body: { success: true, message: 'Data saved successfully' }
    }).as('saveDataSuccess');

    // Attempt to save data
    cy.get('[data-testid="save-button"]').click();

    // Wait for the successful API call
    cy.wait('@saveDataSuccess');

    // Verify error toast is not visible
    cy.get('[data-testid="error-toast"]')
      .should('not.exist');

    // Verify success message appears
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Data saved successfully');
  });
});
